import pandas as pd
import json

def calculate_kelly_position_size(fills_csv_path, bankroll):
    # Read the CSV file
    try:
        fills = pd.read_csv(fills_csv_path)
    except FileNotFoundError:
        return {"error": "File not found"}
    except Exception as e:
        return {"error": str(e)}

    # Filter for BTC trades (assuming symbol contains 'BTC')
    btc_fills = fills[fills['symbol'].str.contains('BTC', case=False, na=False)]

    if len(btc_fills) == 0:
        return {"error": "No BTC trades found"}

    # Calculate win rate and payoff ratio
    positive_pnl = btc_fills[btc_fills['realized_pnl'] > 0]['realized_pnl']
    negative_pnl = btc_fills[btc_fills['realized_pnl'] < 0]['realized_pnl'].abs()

    if len(positive_pnl) == 0 or len(negative_pnl) == 0:
        return {"error": "Insufficient trade data"}

    win_rate = len(positive_pnl) / len(btc_fills)
    avg_win = positive_pnl.mean()
    avg_loss = negative_pnl.mean()
    payoff_ratio = avg_win / avg_loss

    # Calculate Kelly fraction
    kelly_fraction = (win_rate * payoff_ratio - (1 - win_rate)) / payoff_ratio

    # Calculate dollar amount
    amount = kelly_fraction * bankroll

    return {
        "fraction": float(kelly_fraction),
        "amount": float(amount)
    }

# Parameters
fills_path = 'blackbox_os/roles/data_scientist/workflows/mock_data/pipeline_runs/run_8/fills.csv'
bankroll = 50000

# Calculate and print results
result = calculate_kelly_position_size(fills_path, bankroll)
print(json.dumps(result, indent=2))
